package com.triathlon.prep;

import android.content.ContentValues;import android.database.Cursor;import android.database.sqlite.*;
import com.triathlon.prep.core.*;import java.io.*;import java.util.*;import java.util.zip.CRC32;
/** One serialized Android owner; committed rows/claims only, legacy inputs retained unchanged. */
public final class LocalRecordDatabase implements AutoCloseable {
 public static final int AUTO_LIMIT=120000,MANUAL_LIMIT=120000,CLAIM_LIMIT=300000,PAGE_SIZE=100;
 public static final long MAIN_MAX=512L*1024*1024,WAL_MAX=16L*1024*1024;
 private final SQLiteDatabase db;private final File file,wal;private final Verification.Mode mode;private boolean closed;
 public static final class Page {public final List<Verification.Record> rows;public final int page,pageCount,total;Page(List<Verification.Record> rows,int page,int total){this.rows=Collections.unmodifiableList(rows);this.page=page;this.total=total;pageCount=(total+PAGE_SIZE-1)/PAGE_SIZE;}}
 public static final class History {public final List<Verification.Record> automatic;public final List<ManualRecord> manual;public final Set<String> registered;public final int missing,total;History(List<Verification.Record> a,List<ManualRecord> m,int missing,int total,Set<String> registered){automatic=Collections.unmodifiableList(a);manual=Collections.unmodifiableList(m);this.missing=missing;this.total=total;this.registered=Collections.unmodifiableSet(new HashSet<>(registered));}}
 public LocalRecordDatabase(File file,Verification.Mode mode,Verification.RecordStore legacy,ManualRecordStore oldManual,Set<String> oldClaims)throws IOException {
  if(file==null||mode==null||legacy==null||oldManual==null||oldClaims==null)throw new IOException("Explicit private storage inputs required");this.file=file;this.mode=mode;wal=new File(file.getPath()+"-wal");File parent=file.getParentFile();if(parent==null||!parent.exists()&&!parent.mkdirs()||!parent.isDirectory()||file.exists()&&file.length()>MAIN_MAX)throw new IOException("Private ledger unavailable");SQLiteDatabase opened=null;
  try{opened=SQLiteDatabase.openDatabase(file.getPath(),null,SQLiteDatabase.CREATE_IF_NECESSARY);db=opened;if(!db.enableWriteAheadLogging())throw new IOException("Durable WAL unavailable");db.execSQL("PRAGMA synchronous=FULL");if(scalar("PRAGMA journal_size_limit="+WAL_MAX,null)!=WAL_MAX)throw new IOException("WAL bound unavailable");if(db.setMaximumSize(MAIN_MAX)>MAIN_MAX)throw new IOException("Main ledger bound unavailable");
   try(Cursor c=db.rawQuery("PRAGMA quick_check",null)){if(!c.moveToFirst()||!"ok".equals(c.getString(0)))throw new IOException("Ledger integrity failed");}
   int version=db.getVersion();if(version!=0&&version!=1)throw new IOException("Unsupported ledger version");if(version==0){db.beginTransaction();try{db.execSQL("CREATE TABLE automatic(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,stamp INTEGER NOT NULL,mode TEXT NOT NULL,batch TEXT NOT NULL,bib TEXT NOT NULL,verdict TEXT NOT NULL,membership TEXT NOT NULL,payload BLOB NOT NULL,crc INTEGER NOT NULL)");db.execSQL("CREATE INDEX automatic_history ON automatic(mode,stamp DESC,id)");db.execSQL("CREATE INDEX automatic_batch ON automatic(mode,batch,bib,stamp DESC,id DESC)");db.execSQL("CREATE TABLE manual(id TEXT PRIMARY KEY,stamp INTEGER NOT NULL,mode TEXT NOT NULL,batch TEXT NOT NULL,bib TEXT NOT NULL,payload BLOB NOT NULL,crc INTEGER NOT NULL,UNIQUE(mode,batch,bib))");db.execSQL("CREATE INDEX manual_batch ON manual(mode,batch,bib)");db.execSQL("CREATE TABLE claims(digest TEXT PRIMARY KEY)");db.execSQL("CREATE TABLE metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL)");db.setVersion(1);db.setTransactionSuccessful();}finally{db.endTransaction();}}
   if(scalar("SELECT count(*) FROM metadata WHERE key='migrated'",null)==0){List<Verification.Record> a=legacy.list();List<ManualRecord> m=oldManual.list();if(a.size()>AUTO_LIMIT||m.size()>MANUAL_LIMIT||oldClaims.size()>CLAIM_LIMIT)throw new IOException("Legacy capacity invalid");ensureWrite();db.beginTransaction();try{for(Verification.Record r:a){checkMode(r.mode);db.insertOrThrow("automatic",null,automaticValues(r));}for(ManualRecord r:m){checkMode(r.mode);db.insertOrThrow("manual",null,manualValues(r));}for(String hash:oldClaims){if(!hash.matches("[0-9a-f]{64}"))throw new IOException("Invalid legacy reservation");ContentValues v=new ContentValues();v.put("digest",hash);db.insertOrThrow("claims",null,v);}if(count("automatic")!=a.size()||count("manual")!=m.size()||count("claims")!=oldClaims.size())throw new IOException("Legacy migration count mismatch");db.execSQL("INSERT INTO metadata VALUES('migrated','1')");db.setTransactionSuccessful();}finally{db.endTransaction();}checkpoint();}
  }catch(Exception e){if(opened!=null)opened.close();throw io("Private ledger initialization failed",e);}
 }
 private static IOException io(String message,Exception cause){return cause instanceof IOException?(IOException)cause:new IOException(message,cause);}
 private void checkMode(Verification.Mode value)throws IOException{if(value!=mode)throw new IOException("Ledger mode mismatch");}
 private long scalar(String sql,String[] args){try(Cursor c=db.rawQuery(sql,args)){if(!c.moveToFirst())throw new SQLiteException("Missing scalar");return c.getLong(0);}}
 private int count(String table){return (int)scalar("SELECT count(*) FROM "+table,null);}
 private void available()throws IOException{if(closed||!db.isOpen())throw new IOException("Ledger closed");}
 private void checkpoint()throws IOException{try(Cursor c=db.rawQuery("PRAGMA wal_checkpoint(TRUNCATE)",null)){if(!c.moveToFirst()||c.getInt(0)!=0||wal.length()>WAL_MAX)throw new IOException("WAL checkpoint unavailable");}}
 private void ensureWrite()throws IOException{available();if(file.getParentFile().getUsableSpace()<4L*1024*1024)throw new IOException("Insufficient private space");if(wal.length()>WAL_MAX-4L*1024*1024)checkpoint();if(wal.length()>WAL_MAX-4L*1024*1024)throw new IOException("WAL admission limit");}
 private static long crc(byte[] bytes){CRC32 crc=new CRC32();crc.update(bytes);return crc.getValue();}
 private static byte[] checked(Cursor c,int data,int checksum)throws IOException{byte[] bytes=c.getBlob(data);if(crc(bytes)!=c.getLong(checksum))throw new IOException("Ledger payload checksum mismatch");return bytes;}
 private ContentValues automaticValues(Verification.Record r)throws IOException{byte[] payload=RecordCodec.encode(r);ContentValues v=new ContentValues();v.put("id",r.sessionId);v.put("stamp",r.timestamp);v.put("mode",r.mode.name());v.put("batch",r.rosterBatchId);v.put("bib",r.rosterBib);v.put("verdict",r.verdict.name());v.put("membership",r.membership.name());v.put("payload",payload);v.put("crc",crc(payload));return v;}
 private ContentValues manualValues(ManualRecord r)throws IOException{byte[] payload=RecordCodec.encode(r);ContentValues v=new ContentValues();v.put("id",r.id);v.put("stamp",r.timestamp);v.put("mode",r.mode.name());v.put("batch",r.rosterBatchId);v.put("bib",r.rosterBib);v.put("payload",payload);v.put("crc",crc(payload));return v;}
 private Verification.Record automatic(Cursor c)throws IOException{Verification.Record r=RecordCodec.decode(checked(c,0,1));checkMode(r.mode);return r;}
 private ManualRecord manual(Cursor c)throws IOException{ManualRecord r=RecordCodec.decodeManual(checked(c,0,1));checkMode(r.mode);return r;}
 public Verification.RecordStore records(){return new Verification.RecordStore(){public void save(Verification.Record r)throws IOException{saveAutomatic(r);}public CheckIn.State saveCheckIn(Verification.Record r)throws IOException{return saveAutomaticCheckIn(r);}public List<Verification.Record> list()throws IOException{return listAutomatic();}public void clear()throws IOException{throw new IOException("Automatic history deletion is not supported");}};}
 public ManualRecordStore manualRecords(){return new ManualRecordStore(){public List<ManualRecord> list()throws IOException{return listManual();}public ManualRecord commit(ManualRecord r)throws IOException{return saveManual(r);}public ManualRecordStore.Commit commitCheckIn(ManualRecord r)throws IOException{return saveManualCheckIn(r);}public ManualRecord find(Verification.Mode mode,String batch,String bib)throws IOException{return findManual(mode,batch,bib);}};}
 /** Query only the requested trustworthy key; unrelated or unkeyed legacy never blocks this person. */
 private CheckIn.State registration(Verification.Mode requested,String batch,String bib,String currentId)throws IOException {
  if(!CheckIn.validKey(batch,bib))return CheckIn.State.NOT_SUCCESS;boolean unknown=false;
  try(Cursor c=db.rawQuery("SELECT payload,crc FROM automatic WHERE mode=? AND batch=? AND bib=? ORDER BY seq",new String[]{requested.name(),batch,bib})){
   while(c.moveToNext()){try{Verification.Record r=automatic(c);if(!CheckIn.same(r,requested,batch,bib)){unknown=true;continue;}if(CheckIn.trustedSuccess(r))return r.sessionId.equals(currentId)?CheckIn.State.FIRST:CheckIn.State.DUPLICATE;if(r.verdict==Verification.Verdict.PASSED&&r.membership==Verification.Membership.LEGACY_NOT_EVALUATED)unknown=true;}catch(IOException damaged){unknown=true;}}
  }
  try(Cursor c=db.rawQuery("SELECT payload,crc FROM manual WHERE mode=? AND batch=? AND bib=?",new String[]{requested.name(),batch,bib})){while(c.moveToNext()){try{ManualRecord r=manual(c);if(r.mode==requested&&r.rosterBatchId.equals(batch)&&r.rosterBib.equals(bib))return CheckIn.State.DUPLICATE;unknown=true;}catch(IOException damaged){unknown=true;}}}
  return unknown?CheckIn.State.UNLINKABLE:CheckIn.State.FIRST;
 }
 public synchronized void saveAutomatic(Verification.Record r)throws IOException{saveAutomaticCheckIn(r);}
 public synchronized CheckIn.State saveAutomaticCheckIn(Verification.Record r)throws IOException{
  try{checkMode(r.mode);ContentValues v=automaticValues(r);ensureWrite();CheckIn.State state;db.beginTransaction();try{
   state=CheckIn.trustedSuccess(r)?registration(r.mode,r.rosterBatchId,r.rosterBib,r.sessionId):CheckIn.State.NOT_SUCCESS;
   boolean existing=scalar("SELECT count(*) FROM automatic WHERE id=?",new String[]{r.sessionId})!=0;
   if(!existing&&count("automatic")>=AUTO_LIMIT)throw new IOException("Automatic capacity reached");
   // Update preserves durable insertion order for an idempotent save retry.
   if(existing){if(db.update("automatic",v,"id=?",new String[]{r.sessionId})!=1)throw new IOException("Automatic update unconfirmed");}
   else if(db.insertOrThrow("automatic",null,v)<0)throw new IOException("Automatic insert unconfirmed");
   db.setTransactionSuccessful();
  }finally{db.endTransaction();}return state;}catch(Exception e){throw io("Automatic commit failed",e);}
 }
 public synchronized ManualRecord saveManual(ManualRecord r)throws IOException{return saveManualCheckIn(r).record;}
 public synchronized ManualRecordStore.Commit saveManualCheckIn(ManualRecord r)throws IOException{
  try{checkMode(r.mode);ContentValues v=manualValues(r);ensureWrite();ManualRecordStore.Commit outcome;db.beginTransaction();try{
   ManualRecord existing=findManual(r.mode,r.rosterBatchId,r.rosterBib);
   if(existing!=null)outcome=new ManualRecordStore.Commit(existing,CheckIn.State.DUPLICATE);
   else{CheckIn.State state=registration(r.mode,r.rosterBatchId,r.rosterBib,null);if(count("manual")>=MANUAL_LIMIT)throw new IOException("Manual capacity reached");db.insertOrThrow("manual",null,v);outcome=new ManualRecordStore.Commit(r,state);}
   db.setTransactionSuccessful();
  }finally{db.endTransaction();}return outcome;}catch(Exception e){throw io("Manual commit failed",e);}
 }
 public synchronized ManualRecord findManual(Verification.Mode requested,String batch,String bib)throws IOException{available();checkMode(requested);try(Cursor c=db.rawQuery("SELECT payload,crc FROM manual WHERE mode=? AND batch=? AND bib=?",new String[]{requested.name(),batch,bib})){return c.moveToFirst()?manual(c):null;}catch(Exception e){throw io("Manual lookup failed",e);}}
 private synchronized List<Verification.Record> listAutomatic()throws IOException{available();List<Verification.Record> out=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT payload,crc FROM automatic ORDER BY seq",null)){while(c.moveToNext())out.add(automatic(c));return out;}catch(Exception e){throw io("Automatic read failed",e);}}
 private synchronized List<ManualRecord> listManual()throws IOException{available();List<ManualRecord> out=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT payload,crc FROM manual ORDER BY stamp,id",null)){while(c.moveToNext())out.add(manual(c));return out;}catch(Exception e){throw io("Manual read failed",e);}}
 public synchronized AutoPrintPolicy.Claim claimDigest(String digest)throws IOException{if(digest==null||!digest.matches("[0-9a-f]{64}"))return AutoPrintPolicy.Claim.FAILED;try{ensureWrite();db.beginTransaction();try{if(scalar("SELECT count(*) FROM claims WHERE digest=?",new String[]{digest})!=0){db.setTransactionSuccessful();return AutoPrintPolicy.Claim.ALREADY_CLAIMED;}if(count("claims")>=CLAIM_LIMIT)return AutoPrintPolicy.Claim.FAILED;ContentValues v=new ContentValues();v.put("digest",digest);db.insertOrThrow("claims",null,v);db.setTransactionSuccessful();return AutoPrintPolicy.Claim.CLAIMED;}finally{db.endTransaction();}}catch(Exception e){throw io("Reservation commit failed",e);}}
 public synchronized Page page(Verification.Mode requested,String result,int requestedPage)throws IOException{available();checkMode(requested);String condition="mode=?";List<String> params=new ArrayList<>();params.add(requested.name());if(!"ALL".equals(result)){if(result.equals("PASSED")){condition+=" AND membership='MATCHED' AND verdict='PASSED'";}else if(result.equals("REJECTED")){condition+=" AND ((membership='MATCHED' AND verdict='REJECTED') OR (membership='NOT_LISTED' AND verdict<>'CANCELLED'))";}else if(result.equals("UNAVAILABLE")){condition+=" AND NOT ((membership='MATCHED' AND verdict IN ('PASSED','REJECTED')) OR (membership='NOT_LISTED' AND verdict<>'CANCELLED'))";}else throw new IOException("Unknown history filter");}String[] args=params.toArray(new String[0]);try{int total=(int)scalar("SELECT count(*) FROM automatic WHERE "+condition,args),p=Math.max(0,Math.min(requestedPage,Math.max(0,(total-1)/PAGE_SIZE)));List<Verification.Record> out=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT payload,crc FROM automatic WHERE "+condition+" ORDER BY stamp DESC,id LIMIT "+PAGE_SIZE+" OFFSET "+p*PAGE_SIZE,args)){while(c.moveToNext())out.add(automatic(c));}return new Page(out,p,total);}catch(Exception e){throw io("History page failed",e);}}
 public synchronized History exportHistory(RaceRoster roster,Verification.Mode requested)throws IOException{available();checkMode(requested);Set<String> bibs=new HashSet<>();for(RaceRoster.Athlete a:roster.athletes())bibs.add(a.bib);Map<String,Verification.Record> latest=new HashMap<>();List<ManualRecord> manual=new ArrayList<>();Set<String> registered=new HashSet<>();int missing=0;
  try(Cursor c=db.rawQuery("SELECT payload,crc FROM automatic WHERE mode=? AND verdict IN ('PASSED','REJECTED') AND (batch='' OR batch=?) ORDER BY stamp DESC,id DESC",new String[]{requested.name(),roster.batchId})){while(c.moveToNext()){Verification.Record r=automatic(c);if(r.rosterBatchId.isEmpty()){if(r.membership==Verification.Membership.LEGACY_NOT_EVALUATED||r.membership==Verification.Membership.MATCHED)missing++;continue;}if(r.membership==Verification.Membership.LEGACY_NOT_EVALUATED){missing++;continue;}if(r.membership!=Verification.Membership.MATCHED)continue;if(r.rosterBib.isEmpty()||!bibs.contains(r.rosterBib)){missing++;continue;}if(CheckIn.trustedSuccess(r))registered.add(r.rosterBib);if(!latest.containsKey(r.rosterBib))latest.put(r.rosterBib,r);}}
  catch(Exception e){throw io("Automatic export attribution failed",e);}
  try(Cursor c=db.rawQuery("SELECT payload,crc FROM manual WHERE mode=? AND batch=?",new String[]{requested.name(),roster.batchId})){while(c.moveToNext()){ManualRecord r=manual(c);if(!bibs.contains(r.rosterBib))missing++;else manual.add(r);}}catch(Exception e){throw io("Manual export attribution failed",e);}
  return new History(new ArrayList<>(latest.values()),manual,missing,count("automatic")+count("manual"),registered);
 }
 public synchronized int[] counts()throws IOException{available();return new int[]{count("automatic"),count("manual"),count("claims")};}
 @Override public synchronized void close(){if(closed)return;closed=true;db.close();}
}


